using System;
using System.Net.Http;
using System.Security.Authentication;
using System.Threading.Tasks;

// PROGRAM: Mengonfigurasi Client dengan Proteksi Minimal TLS 1.3
var handler = new HttpClientHandler
{
    // Hanya mengizinkan TLS 1.2 dan TLS 1.3 (Protokol usang SSL 3.0 / TLS 1.0 ditolak mutlak!)
    SslProtocols = SslProtocols.Tls12 | SslProtocols.Tls13
};

using var client = new HttpClient(handler);

try
{
    Console.WriteLine("Menghubungkan ke endpoint aman via TLS 1.2 / TLS 1.3...");
    var response = await client.GetAsync("https://api.github.com");
    Console.WriteLine($"Handshake Sukses! Status: {response.StatusCode}");
}
catch (Exception ex)
{
    Console.WriteLine($"Koneksi gagal atau ditolak oleh protokol keamanan: {ex.Message}");
}

