using System;

public class TlsSecurityChecker
{
    public static bool IsSecureTlsProtocol(string? protocolName)
    {
        if (string.IsNullOrWhiteSpace(protocolName)) return false;

        string clean = protocolName.Trim();
        return string.Equals(clean, "TLS 1.2", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(clean, "TLS 1.3", StringComparison.OrdinalIgnoreCase);
    }

    public static void Main()
    {
        Console.WriteLine(IsSecureTlsProtocol("TLS 1.3"));
        Console.WriteLine(IsSecureTlsProtocol("TLS 1.0"));
        Console.WriteLine(IsSecureTlsProtocol("SSL 3.0"));
    }
}
